"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95280"],{4718(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.inscricao_sem_conjunto_basico","status":422,"titulo":"O conjunto b\xe1sico de dados do candidato n\xe3o est\xe1 todo em formul\xe1rio obrigat\xf3rio da fase que coleta inscri\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.inscricao_sem_conjunto_basico","requisitos":["UNI-REQ-0151"],"oQueAconteceu":["O processo declara que a inscri\xe7\xe3o \xe9 feita pelo sistema, e os formul\xe1rios obrigat\xf3rios da fase que coleta inscri\xe7\xe3o n\xe3o coletam, juntos, todos os dados do conjunto b\xe1sico do candidato (UNI-REQ-0151: nome, CPF, RG, nacionalidade, data de nascimento, endere\xe7o e os demais dados b\xe1sicos). Os dados do conjunto ficam num formul\xe1rio obrigat\xf3rio da fase de inscri\xe7\xe3o, em campo de resposta \xfanica, e falta pelo menos um. A recusa sai com **422**, e o `detail` diz quantos dados faltam."],"comoResolver":["Coloque os dados que faltam num formul\xe1rio obrigat\xf3rio da fase de inscri\xe7\xe3o: grave de novo o formul\xe1rio e, depois, os itens dele, o que rep\xf5e a se\xe7\xe3o reservada com todos os dados do conjunto. Ou parta do modelo de inscri\xe7\xe3o do tipo do processo, que j\xe1 traz o conjunto b\xe1sico completo. Depois disso, publique de novo."],"ondeAparece":["Publica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);